package com.basespringboot.model;

import java.util.ArrayList;
import java.util.List;

import jakarta.persistence.*;
import lombok.Getter;
import lombok.Setter;
// JPA entity representing a garage that owns multiple cars
@Entity 
@Getter 
@Setter 
public class Garage {
    
    // Primary key auto-generated by the database
    @Id 
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String name;
    private String address;

    // Cascade operations and orphan removal apply to child cars; loaded eagerly
    @OneToMany(mappedBy = "garage",cascade = CascadeType.ALL,orphanRemoval = true, fetch = FetchType.EAGER)
    private List<Car> cars = new ArrayList<>();

}
